"""Keychain tests: token format, self-verification, TS-file compatibility."""

import base64
import re

import pytest
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

from hub_service_py import keychain

# Key generated by the TS reference keychain (hub-service/keychain.ts):
# base64(48-byte PKCS8 DER private || 44-byte SPKI DER public).
TS_AUTH = "MC4CAQAwBQYDK2VwBCIEINguo0cc0FACJ0oRV3V/+ZqIyj04ON5wdMJGH4a/do8CMCowBQYDK2VwAyEAHZSDpmbLRjLrOyNMugsStFqK5EYcNluUekE4di+FalQ="
TS_PUB = "MCowBQYDK2VwAyEAHZSDpmbLRjLrOyNMugsStFqK5EYcNluUekE4di+FalQ="


def test_sign_token_shape():
    keychain.set_key_path("/tmp/hub_service_py_test_auth")
    token = keychain.sign()
    parts = token.split(".")
    assert parts[0] == "key"
    assert parts[1] == keychain.public_key()
    assert parts[2]  # signature
    assert re.fullmatch(r"\d+", parts[3])  # decimal expiry (TS parity)
    assert int(parts[3]) >= int(__import__("time").time())


def test_signature_verifies():
    keychain.set_key_path("/tmp/hub_service_py_test_auth_2")
    token = keychain.sign(expires=30)
    _, pub_b64, sig_b64, expiry = token.split(".")
    # pub_b64 is the 44-byte SPKI DER; the raw key is its last 32 bytes.
    spki = base64.b64decode(pub_b64)
    pub = Ed25519PublicKey.from_public_bytes(spki[-32:])
    pub.verify(base64.b64decode(sig_b64), expiry.encode())
    # signature is over the decimal expiry string
    assert len(base64.b64decode(sig_b64)) == 64


def test_auth_file_round_trip():
    keychain.set_key_path("/tmp/hub_service_py_test_auth_3")
    pub1 = keychain.public_key()
    pub2 = keychain.public_key()  # cached; same
    assert pub1 == pub2
    # A second instance (fresh module state) loads the same file.
    import importlib

    fresh = importlib.reload(keychain)
    fresh.set_key_path("/tmp/hub_service_py_test_auth_3")
    assert fresh.public_key() == pub1


def test_loads_ts_generated_key():
    """The py keychain must read a TS-generated auth file byte-for-byte."""
    keychain.set_key_path("/tmp/hub_service_py_ts_auth")
    import pathlib

    pathlib.Path("/tmp/hub_service_py_ts_auth").write_text(TS_AUTH)
    assert keychain.public_key() == TS_PUB
    token = keychain.sign()
    parts = token.split(".")
    assert parts[1] == TS_PUB
    # Signature verifies against the TS public key.
    spki = base64.b64decode(TS_PUB)
    pub = Ed25519PublicKey.from_public_bytes(spki[-32:])
    pub.verify(base64.b64decode(parts[2]), parts[3].encode())
